def commit(state, batch):
    balances = dict(state['balances'])
    seen = {eid: list(entry) for eid, entry in state['seen'].items()}
    for event in batch:
        try:
            eid, src, dst, amount = event
        except Exception:
            raise ValueError("invalid")
        if not isinstance(eid, str):
            raise ValueError("invalid")
        if not isinstance(src, str) or not isinstance(dst, str):
            raise ValueError("invalid")
        if src == dst:
            raise ValueError("invalid")
        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError("invalid")
        if src not in balances or dst not in balances:
            raise ValueError("invalid")
        if eid in seen:
            if list(seen[eid]) == [src, dst, amount]:
                continue
            raise ValueError("conflict")
        if balances[src] < amount:
            raise ValueError("funds")
        balances[src] -= amount
        balances[dst] += amount
        seen[eid] = [src, dst, amount]
    result = dict(state)
    result['balances'] = balances
    result['seen'] = seen
    return result

