from ledger import commit

def restore(snapshot, batches):
    if isinstance(snapshot, dict) and 'balances' in snapshot and isinstance(snapshot['balances'], dict):
        seen = snapshot.get('seen', {})
        if not isinstance(seen, dict):
            seen = {}
        state = dict(snapshot)
        state['balances'] = dict(snapshot['balances'])
        state['seen'] = {eid: list(entry) for eid, entry in seen.items()}
    else:
        state = {'balances': dict(snapshot), 'seen': {}}
    rejected = []
    for index, batch in enumerate(batches):
        try:
            state = commit(state, batch)
        except ValueError:
            rejected.append(index)
    return [state, rejected]
